const fs = require('fs'), path = require('path')
const files = {}

files["supabase/migrations/006_food.sql"] = "-- ============================================================\n-- FYP.STUDIO — Módulo Gastronomía\n-- Ejecutar DESPUÉS de 005_barbershop.sql\n-- ============================================================\n\n-- ── Horarios del negocio ──────────────────────────────────────\ncreate table if not exists business_hours (\n  id           uuid primary key default uuid_generate_v4(),\n  business_id  uuid not null references businesses(id) on delete cascade,\n  branch_id    uuid references branches(id) on delete cascade,\n  day_of_week  int not null check (day_of_week between 0 and 6),\n  is_open      boolean not null default true,\n  open_time    time not null default '09:00',\n  close_time   time not null default '22:00',\n  unique(business_id, day_of_week)\n);\n\nalter table business_hours enable row level security;\ncreate policy \"comercio gestiona horarios\"\n  on business_hours for all\n  using  (business_id = get_my_business_id() or is_superadmin())\n  with check (business_id = get_my_business_id() or is_superadmin());\ncreate policy \"tienda lee horarios\"\n  on business_hours for select using (true);\n\n-- ── Combos / Promociones ─────────────────────────────────────\ncreate table if not exists combos (\n  id           uuid primary key default uuid_generate_v4(),\n  business_id  uuid not null references businesses(id) on delete cascade,\n  name         text not null,\n  description  text,\n  price        numeric(10,2) not null,\n  image_url    text,\n  active       boolean not null default true,\n  featured     boolean not null default false,\n  valid_from   timestamptz,\n  valid_until  timestamptz,\n  created_at   timestamptz not null default now()\n);\n\ncreate table if not exists combo_items (\n  id         uuid primary key default uuid_generate_v4(),\n  combo_id   uuid not null references combos(id) on delete cascade,\n  product_id uuid references products(id) on delete set null,\n  product_name text not null,\n  quantity   int not null default 1\n);\n\nalter table combos      enable row level security;\nalter table combo_items enable row level security;\n\ncreate policy \"comercio gestiona combos\"\n  on combos for all\n  using  (business_id = get_my_business_id() or is_superadmin())\n  with check (business_id = get_my_business_id() or is_superadmin());\ncreate policy \"tienda lee combos activos\"\n  on combos for select using (active = true);\ncreate policy \"todos leen combo_items\"\n  on combo_items for all\n  using  (true) with check (true);\n\n-- ── Agregar campo delivery_fee y pickup_enabled a businesses ──\nalter table businesses\n  add column if not exists delivery_fee    numeric(10,2) default 0;\nalter table businesses\n  add column if not exists delivery_enabled boolean default true;\nalter table businesses\n  add column if not exists pickup_enabled   boolean default true;\nalter table businesses\n  add column if not exists min_order        numeric(10,2) default 0;\nalter table businesses\n  add column if not exists estimated_time   text default '30-45 min';\n\n-- ── Horarios default para negocios food ──────────────────────\ncreate or replace function create_default_hours()\nreturns trigger language plpgsql as $$\nbegin\n  if new.vertical_type = 'food' then\n    insert into business_hours (business_id, day_of_week, is_open, open_time, close_time)\n    values\n      (new.id, 0, true,  '11:00', '23:00'),\n      (new.id, 1, true,  '11:00', '23:00'),\n      (new.id, 2, true,  '11:00', '23:00'),\n      (new.id, 3, true,  '11:00', '23:00'),\n      (new.id, 4, true,  '11:00', '23:00'),\n      (new.id, 5, true,  '11:00', '00:00'),\n      (new.id, 6, true,  '11:00', '00:00')\n    on conflict do nothing;\n  end if;\n  return new;\nend;\n$$;\n\ncreate trigger trg_create_default_hours\n  after insert on businesses\n  for each row execute function create_default_hours();\n\n-- Realtime para orders (ya estaba, confirmar)\n-- alter publication supabase_realtime add table orders;\n"

files["types/index.ts"] = "export type Plan = 'basic' | 'pro' | 'premium'\nexport type SubscriptionStatus = 'trial' | 'active' | 'past_due' | 'canceled' | 'suspended'\nexport type OrderStatus = 'pending' | 'confirmed' | 'preparing' | 'ready' | 'shipped' | 'delivered' | 'cancelled'\nexport type PaymentStatus = 'unpaid' | 'paid' | 'refunded'\nexport type DeliveryType = 'delivery' | 'pickup'\nexport type UserRole = 'owner' | 'staff' | 'superadmin'\nexport type AIGenerationType = 'product' | 'promo' | 'insights'\n\nexport interface Business {\n  id: string; name: string; slug: string; description?: string | null\n  logo_url?: string | null; banner_url?: string | null; whatsapp?: string | null\n  address?: string | null; currency: string; primary_color: string\n  secondary_color: string; plan: Plan; active: boolean\n  subscription_status: SubscriptionStatus; subscription_expires_at?: string | null\n  instagram?: string | null; facebook?: string | null; tiktok?: string | null\n  website?: string | null; vertical_type?: string | null; enabled_modules?: string[] | null; created_at: string; updated_at: string\n}\n\nexport interface Profile {\n  id: string; user_id: string; business_id: string\n  role: UserRole; created_at: string; business?: Business\n}\n\nexport interface Category {\n  id: string; business_id: string; name: string; slug: string\n  sort_order: number; active: boolean; created_at: string\n}\n\nexport interface Product {\n  id: string; business_id: string; category_id?: string | null\n  name: string; slug: string; description?: string | null; price: number\n  images: string[]; tags: string[]; stock?: number | null; featured: boolean\n  active: boolean; seo_title?: string | null; seo_desc?: string | null\n  created_at: string; updated_at: string; category?: Category | null\n}\n\nexport interface Customer {\n  id: string; business_id: string; name: string; phone?: string | null\n  address?: string | null; email?: string | null; total_orders: number\n  total_spent: number; created_at: string; updated_at: string\n}\n\nexport interface Order {\n  id: string; business_id: string; customer_id?: string | null\n  order_number: number; status: OrderStatus; payment_status: PaymentStatus\n  confirmed_sale: boolean; delivery_type: DeliveryType; subtotal: number\n  total: number; comment?: string | null; customer_name: string\n  customer_phone?: string | null; customer_address?: string | null\n  created_at: string; updated_at: string; items?: OrderItem[]; customer?: Customer | null\n}\n\nexport interface OrderItem {\n  id: string; order_id: string; product_id?: string | null\n  product_name: string; unit_price: number; quantity: number; subtotal: number\n  product?: Product | null\n}\n\nexport interface CartItem { product: Product; quantity: number }\n\nexport interface CheckoutFormData {\n  name: string; phone: string; address?: string\n  delivery_type: DeliveryType; comment?: string\n}\n\nexport interface CreateOrderResponse { orderId: string; orderNumber: number }\n\nexport interface AIProductOutput {\n  name: string; description: string; category: string; tags: string[]\n  instagram_copy: string; whatsapp_copy: string; hashtags: string[]\n  seo_title: string; seo_description: string\n}\n\nexport interface AIPromoOutput {\n  title: string; body: string; instagram_story: string\n  whatsapp_message: string; cta: string\n}\n\nexport interface DashboardStats {\n  pendingOrders: number; confirmedOrders: number; totalRevenue: number\n  todayRevenue: number; totalProducts: number; totalCustomers: number\n  recentOrders: Order[]; topProducts: { name: string; count: number; revenue: number }[]\n  cancelRate?: number\n}\n\n// ── Inventario ────────────────────────────────────────────────\n\nexport interface InventoryCategory {\n  id: string\n  business_id: string\n  name: string\n  color: string\n  icon: string\n  created_at: string\n}\n\nexport type MovementType = 'entrada' | 'salida' | 'ajuste' | 'devolucion'\n\nexport interface InventoryItem {\n  id: string\n  business_id: string\n  category_id?: string | null\n  product_id?: string | null\n  name: string\n  sku?: string | null\n  unit: string\n  stock_current: number\n  stock_min: number\n  stock_max?: number | null\n  cost_price?: number | null\n  supplier?: string | null\n  notes?: string | null\n  active: boolean\n  created_at: string\n  updated_at: string\n  // joins\n  category?: InventoryCategory | null\n  product?: { name: string } | null\n}\n\nexport interface InventoryMovement {\n  id: string\n  business_id: string\n  item_id: string\n  order_id?: string | null\n  type: MovementType\n  quantity: number\n  stock_before: number\n  stock_after: number\n  reason?: string | null\n  created_by?: string | null\n  created_at: string\n  item?: InventoryItem | null\n}\n\nexport type StockStatus = 'ok' | 'low' | 'critical' | 'out'\n\nexport function getStockStatus(item: InventoryItem): StockStatus {\n  if (item.stock_current <= 0) return 'out'\n  if (item.stock_current <= item.stock_min * 0.5) return 'critical'\n  if (item.stock_current <= item.stock_min) return 'low'\n  return 'ok'\n}\n\n// ── Proveedores ───────────────────────────────────────────────\n\nexport interface Supplier {\n  id: string\n  business_id: string\n  name: string\n  contact_name?: string | null\n  phone?: string | null\n  email?: string | null\n  address?: string | null\n  city?: string | null\n  notes?: string | null\n  active: boolean\n  created_at: string\n  updated_at: string\n  // computed\n  products?: SupplierProduct[]\n}\n\nexport interface SupplierProduct {\n  id: string\n  supplier_id: string\n  business_id: string\n  inventory_item_id?: string | null\n  product_name: string\n  sku_supplier?: string | null\n  unit: string\n  price?: number | null\n  min_order?: number | null\n  lead_days?: number | null\n  notes?: string | null\n  created_at: string\n  updated_at: string\n  // join\n  inventory_item?: { name: string } | null\n}\n\n// ── Barbería / Belleza ────────────────────────────────────────\n\nexport interface Branch {\n  id: string\n  business_id: string\n  name: string\n  address?: string | null\n  phone?: string | null\n  whatsapp?: string | null\n  city?: string | null\n  is_main: boolean\n  active: boolean\n  created_at: string\n}\n\nexport interface Staff {\n  id: string\n  business_id: string\n  branch_id?: string | null\n  name: string\n  role: string\n  bio?: string | null\n  avatar_url?: string | null\n  phone?: string | null\n  color: string\n  active: boolean\n  created_at: string\n  updated_at: string\n  branch?: Branch | null\n}\n\nexport interface StaffSchedule {\n  id: string\n  staff_id: string\n  business_id: string\n  day_of_week: number  // 0=Dom, 1=Lun, 2=Mar...\n  start_time: string   // '09:00'\n  end_time: string     // '18:00'\n  break_start?: string | null\n  break_end?: string | null\n  is_working: boolean\n}\n\nexport type BookingStatus = 'pending' | 'confirmed' | 'done' | 'cancelled' | 'noshow'\n\nexport interface Booking {\n  id: string\n  business_id: string\n  branch_id?: string | null\n  staff_id?: string | null\n  product_id?: string | null\n  customer_name: string\n  customer_phone?: string | null\n  customer_email?: string | null\n  date: string         // 'YYYY-MM-DD'\n  start_time: string   // 'HH:MM'\n  end_time: string\n  duration_min: number\n  status: BookingStatus\n  notes?: string | null\n  price?: number | null\n  source: string\n  created_at: string\n  updated_at: string\n  // joins\n  staff?: Staff | null\n  branch?: Branch | null\n  product?: { name: string; price: number } | null\n}\n\n// Page Builder\nexport interface PageConfig {\n  theme: {\n    primaryColor: string\n    secondaryColor: string\n    bgColor: string\n    textColor: string\n    font: string\n    borderRadius: 'none' | 'sm' | 'md' | 'lg' | 'full'\n    style: 'modern' | 'minimal' | 'bold' | 'elegant'\n  }\n  hero: {\n    enabled: boolean\n    title: string\n    subtitle: string\n    ctaText: string\n    ctaAction: 'book' | 'whatsapp' | 'scroll'\n    backgroundType: 'color' | 'image' | 'gradient'\n    backgroundValue: string\n  }\n  sections: PageSection[]\n}\n\nexport interface PageSection {\n  id: string\n  type: 'services' | 'team' | 'gallery' | 'testimonials' | 'contact' | 'hours' | 'promo'\n  enabled: boolean\n  title: string\n  order: number\n}\n\n// ── Gastronomía ───────────────────────────────────────────────\n\nexport interface BusinessHours {\n  id: string\n  business_id: string\n  branch_id?: string | null\n  day_of_week: number\n  is_open: boolean\n  open_time: string\n  close_time: string\n}\n\nexport interface Combo {\n  id: string\n  business_id: string\n  name: string\n  description?: string | null\n  price: number\n  image_url?: string | null\n  active: boolean\n  featured: boolean\n  valid_from?: string | null\n  valid_until?: string | null\n  created_at: string\n  items?: ComboItem[]\n}\n\nexport interface ComboItem {\n  id: string\n  combo_id: string\n  product_id?: string | null\n  product_name: string\n  quantity: number\n}\n\nexport type KitchenStatus = 'pending' | 'confirmed' | 'preparing' | 'ready' | 'shipped' | 'delivered' | 'cancelled'\n\nexport const KITCHEN_FLOW: KitchenStatus[] = [\n  'pending', 'confirmed', 'preparing', 'ready', 'shipped', 'delivered'\n]\n"

files["app/admin/food/page.tsx"] = "// app/admin/food/page.tsx\nimport { createClient } from '@/lib/supabase/server'\nimport { redirect } from 'next/navigation'\nimport FoodHub from './FoodHub'\nimport type { Order, Product, Category, BusinessHours } from '@/types'\n\nexport const metadata = { title: 'Cocina & Pedidos' }\nexport const dynamic = 'force-dynamic'\n\nexport default async function FoodPage() {\n  const supabase = await createClient()\n  const { data: { user } } = await supabase.auth.getUser()\n  if (!user) redirect('/auth/login')\n\n  const { data: profile } = await supabase\n    .from('profiles')\n    .select('business_id, business:businesses(*)')\n    .eq('user_id', user.id)\n    .single()\n\n  if (!profile?.business_id) redirect('/admin/onboarding')\n\n  const bid = profile.business_id\n  const biz = profile.business as Record<string, unknown>\n\n  const today = new Date().toISOString().split('T')[0]\n\n  const [ordersRes, productsRes, catsRes, hoursRes] = await Promise.all([\n    supabase\n      .from('orders')\n      .select('*, items:order_items(product_name, quantity, unit_price, subtotal)')\n      .eq('business_id', bid)\n      .gte('created_at', today + 'T00:00:00')\n      .order('created_at', { ascending: false }),\n    supabase\n      .from('products')\n      .select('*, category:categories(name)')\n      .eq('business_id', bid)\n      .eq('active', true)\n      .order('featured', { ascending: false })\n      .order('name'),\n    supabase\n      .from('categories')\n      .select('*')\n      .eq('business_id', bid)\n      .eq('active', true)\n      .order('sort_order'),\n    supabase\n      .from('business_hours')\n      .select('*')\n      .eq('business_id', bid)\n      .order('day_of_week'),\n  ])\n\n  return (\n    <FoodHub\n      businessId={bid}\n      business={biz}\n      orders={(ordersRes.data ?? []) as Order[]}\n      products={(productsRes.data ?? []) as Product[]}\n      categories={(catsRes.data ?? []) as Category[]}\n      hours={(hoursRes.data ?? []) as BusinessHours[]}\n    />\n  )\n}\n"

files["app/admin/food/FoodHub.tsx"] = "// app/admin/food/FoodHub.tsx\n'use client'\nimport { useState, useMemo, useEffect } from 'react'\nimport { createClient } from '@/lib/supabase/client'\nimport {\n  ChefHat, ShoppingBag, BarChart2, Clock, Settings2,\n  Check, X, ChevronRight, RefreshCw, MessageCircle,\n  Loader2, Phone, MapPin, Package, Plus, Minus,\n  Bell, Zap, TrendingUp,\n} from 'lucide-react'\nimport { cn, formatPrice, orderStatusLabel, orderStatusColor } from '@/lib/utils'\nimport type { Order, Product, Category, BusinessHours, OrderItem } from '@/types'\n\ntype Tab = 'kitchen' | 'orders' | 'menu' | 'hours' | 'stats'\n\nconst KITCHEN_COLS = [\n  { status: 'pending',   label: '🔔 Nuevos',      bg: '#FFF7ED', border: '#FED7AA' },\n  { status: 'confirmed', label: '✅ Confirmados',  bg: '#EFF6FF', border: '#BFDBFE' },\n  { status: 'preparing', label: '👨‍🍳 En cocina',   bg: '#FDF4FF', border: '#E9D5FF' },\n  { status: 'ready',     label: '🛵 Listo',        bg: '#F0FDF4', border: '#BBF7D0' },\n]\n\nconst DAYS_ES = ['Dom','Lun','Mar','Mié','Jue','Vie','Sáb']\n\ninterface Props {\n  businessId: string\n  business: Record<string, unknown>\n  orders: Order[]\n  products: Product[]\n  categories: Category[]\n  hours: BusinessHours[]\n}\n\nexport default function FoodHub({ businessId, business, orders: initialOrders, products, categories, hours: initialHours }: Props) {\n  const supabase = createClient()\n  const [tab, setTab] = useState<Tab>('kitchen')\n  const [orders, setOrders] = useState<Order[]>(initialOrders)\n  const [hours, setHours] = useState<BusinessHours[]>(initialHours)\n  const [updating, setUpdating] = useState<string | null>(null)\n  const [newOrderAlert, setNewOrderAlert] = useState(false)\n\n  const color = (business.primary_color as string) ?? '#FF5722'\n  const currency = (business.currency as string) ?? 'UYU'\n  const whatsapp = (business.whatsapp as string) ?? ''\n\n  // Realtime — nuevos pedidos\n  useEffect(() => {\n    const channel = supabase\n      .channel('food-orders')\n      .on('postgres_changes', {\n        event: 'INSERT',\n        schema: 'public',\n        table: 'orders',\n        filter: `business_id=eq.${businessId}`,\n      }, async (payload) => {\n        // Cargar items del nuevo pedido\n        const { data: items } = await supabase\n          .from('order_items')\n          .select('*')\n          .eq('order_id', payload.new.id)\n\n        const newOrder = { ...payload.new, items: items ?? [] } as Order\n        setOrders(prev => [newOrder, ...prev])\n        setNewOrderAlert(true)\n        setTimeout(() => setNewOrderAlert(false), 5000)\n        // Vibración en mobile\n        if ('vibrate' in navigator) navigator.vibrate([200, 100, 200])\n      })\n      .subscribe()\n\n    return () => { supabase.removeChannel(channel) }\n  }, [businessId])\n\n  async function updateOrderStatus(orderId: string, status: string) {\n    setUpdating(orderId)\n    await supabase.from('orders').update({ status }).eq('id', orderId)\n    setOrders(prev => prev.map(o => o.id === orderId ? { ...o, status: status as Order['status'] } : o))\n    setUpdating(null)\n  }\n\n  // Pedidos por estado (solo hoy)\n  const byStatus = useMemo(() => {\n    const map: Record<string, Order[]> = {}\n    KITCHEN_COLS.forEach(c => { map[c.status] = [] })\n    orders.forEach(o => { if (map[o.status]) map[o.status].push(o) })\n    return map\n  }, [orders])\n\n  const todayRevenue = orders.filter(o => o.confirmed_sale).reduce((a, o) => a + o.total, 0)\n  const pendingCount = orders.filter(o => o.status === 'pending').length\n\n  // Abrir WhatsApp cliente\n  function waClient(order: Order) {\n    if (!order.customer_phone) return\n    const msg = encodeURIComponent(`Hola ${order.customer_name}! Tu pedido #${String(order.order_number).padStart(4,'0')} está listo.`)\n    window.open(`https://wa.me/${order.customer_phone.replace(/\\D/g,'')}?text=${msg}`)\n  }\n\n  return (\n    <div className=\"space-y-4 animate-fade-in pb-4\">\n\n      {/* Header */}\n      <div className=\"flex items-start justify-between gap-3\">\n        <div>\n          <h1 className=\"text-xl lg:text-2xl font-bold text-gray-900 tracking-tight flex items-center gap-2\">\n            <ChefHat size={22} style={{ color }} />\n            Cocina & Pedidos\n          </h1>\n          <p className=\"text-xs text-gray-400 mt-0.5\">\n            {new Date().toLocaleDateString('es-UY', { weekday: 'long', day: 'numeric', month: 'long' })}\n          </p>\n        </div>\n\n        {/* Alerta nuevo pedido */}\n        {newOrderAlert && (\n          <div className=\"flex items-center gap-2 rounded-2xl px-4 py-2 text-white text-sm font-semibold animate-bounce\"\n            style={{ background: color }}>\n            <Bell size={14} /> ¡Nuevo pedido!\n          </div>\n        )}\n      </div>\n\n      {/* Stats rápidas */}\n      <div className=\"grid grid-cols-3 gap-3\">\n        {[\n          { label: 'Hoy', value: orders.length, icon: ShoppingBag, color: '#1565FF' },\n          { label: 'Pendientes', value: pendingCount, icon: Clock, color: pendingCount > 0 ? '#F59E0B' : '#9CA3AF' },\n          { label: 'Ingresos', value: formatPrice(todayRevenue, currency), icon: TrendingUp, color: '#10B981' },\n        ].map(({ label, value, icon: Icon, color: c }) => (\n          <div key={label} className=\"bg-white rounded-2xl border border-gray-100 p-3 shadow-sm text-center\">\n            <Icon size={16} className=\"mx-auto mb-1.5\" style={{ color: c }} />\n            <p className=\"text-base font-bold text-gray-900\">{value}</p>\n            <p className=\"text-[10px] text-gray-400\">{label}</p>\n          </div>\n        ))}\n      </div>\n\n      {/* Tabs */}\n      <div className=\"flex items-center gap-1 overflow-x-auto scrollbar-hide bg-gray-100 rounded-xl p-1\">\n        {([\n          { key: 'kitchen', label: 'Cocina',   icon: ChefHat    },\n          { key: 'orders',  label: 'Pedidos',  icon: ShoppingBag },\n          { key: 'hours',   label: 'Horarios', icon: Clock       },\n          { key: 'stats',   label: 'Stats',    icon: BarChart2   },\n        ] as { key: Tab; label: string; icon: React.ElementType }[]).map(({ key, label, icon: Icon }) => (\n          <button key={key} onClick={() => setTab(key)}\n            className={cn('flex items-center gap-1.5 rounded-lg px-3 py-2 text-xs font-medium shrink-0 transition-all',\n              tab === key ? 'bg-white text-gray-900 shadow-sm' : 'text-gray-500 hover:text-gray-700')}>\n            <Icon size={13} />{label}\n            {key === 'kitchen' && pendingCount > 0 && (\n              <span className=\"flex h-4 w-4 items-center justify-center rounded-full text-[9px] font-bold text-white\"\n                style={{ background: color }}>\n                {pendingCount}\n              </span>\n            )}\n          </button>\n        ))}\n      </div>\n\n      {/* ── KITCHEN VIEW — Columnas kanban ── */}\n      {tab === 'kitchen' && (\n        <div className=\"space-y-4\">\n          {/* Mobile: lista por estados */}\n          <div className=\"lg:hidden space-y-4\">\n            {KITCHEN_COLS.map(col => (\n              <div key={col.status}>\n                <div className=\"flex items-center justify-between mb-2\">\n                  <p className=\"text-sm font-semibold text-gray-700\">{col.label}</p>\n                  <span className=\"text-xs text-gray-400\">{byStatus[col.status]?.length ?? 0}</span>\n                </div>\n                {(byStatus[col.status] ?? []).length === 0 ? (\n                  <div className=\"rounded-xl border border-dashed border-gray-200 py-4 text-center\">\n                    <p className=\"text-xs text-gray-300\">Sin pedidos</p>\n                  </div>\n                ) : (\n                  <div className=\"space-y-2\">\n                    {(byStatus[col.status] ?? []).map(order => (\n                      <KitchenCard\n                        key={order.id}\n                        order={order}\n                        currency={currency}\n                        updating={updating === order.id}\n                        onStatus={updateOrderStatus}\n                        onWA={() => waClient(order)}\n                        color={color}\n                      />\n                    ))}\n                  </div>\n                )}\n              </div>\n            ))}\n          </div>\n\n          {/* Desktop: kanban horizontal */}\n          <div className=\"hidden lg:grid grid-cols-4 gap-4\">\n            {KITCHEN_COLS.map(col => (\n              <div key={col.status} className=\"rounded-2xl p-3 min-h-[200px]\"\n                style={{ background: col.bg, border: `1px solid ${col.border}` }}>\n                <div className=\"flex items-center justify-between mb-3\">\n                  <p className=\"text-xs font-bold text-gray-700\">{col.label}</p>\n                  <span className=\"text-xs font-bold rounded-full h-5 w-5 flex items-center justify-center bg-white text-gray-600\">\n                    {byStatus[col.status]?.length ?? 0}\n                  </span>\n                </div>\n                <div className=\"space-y-2\">\n                  {(byStatus[col.status] ?? []).map(order => (\n                    <KitchenCard\n                      key={order.id}\n                      order={order}\n                      currency={currency}\n                      updating={updating === order.id}\n                      onStatus={updateOrderStatus}\n                      onWA={() => waClient(order)}\n                      color={color}\n                      compact\n                    />\n                  ))}\n                </div>\n              </div>\n            ))}\n          </div>\n        </div>\n      )}\n\n      {/* ── ORDERS — Lista completa ── */}\n      {tab === 'orders' && (\n        <div className=\"space-y-2\">\n          {orders.length === 0 ? (\n            <div className=\"rounded-2xl border-2 border-dashed border-gray-200 py-14 text-center\">\n              <ShoppingBag size={28} className=\"mx-auto text-gray-200 mb-3\" />\n              <p className=\"text-sm text-gray-400\">Sin pedidos hoy</p>\n            </div>\n          ) : (\n            orders.map(order => (\n              <OrderRow\n                key={order.id}\n                order={order}\n                currency={currency}\n                updating={updating === order.id}\n                onStatus={updateOrderStatus}\n                onWA={() => waClient(order)}\n                color={color}\n              />\n            ))\n          )}\n        </div>\n      )}\n\n      {/* ── HORARIOS ── */}\n      {tab === 'hours' && (\n        <HoursManager\n          businessId={businessId}\n          hours={hours}\n          onUpdate={setHours}\n          color={color}\n        />\n      )}\n\n      {/* ── STATS ── */}\n      {tab === 'stats' && (\n        <FoodStats orders={orders} currency={currency} color={color} />\n      )}\n    </div>\n  )\n}\n\n// ── Kitchen Card ──────────────────────────────────────────────\nfunction KitchenCard({ order, currency, updating, onStatus, onWA, color, compact = false }: {\n  order: Order; currency: string; updating: boolean\n  onStatus: (id: string, s: string) => void\n  onWA: () => void; color: string; compact?: boolean\n}) {\n  const NEXT: Record<string, { label: string; status: string; bg: string }> = {\n    pending:   { label: 'Confirmar',   status: 'confirmed', bg: color    },\n    confirmed: { label: 'A cocina →',  status: 'preparing', bg: '#7C3AED'},\n    preparing: { label: '¡Listo! →',   status: 'ready',     bg: '#059669'},\n    ready:     { label: 'Enviado →',   status: 'shipped',   bg: '#1565FF'},\n    shipped:   { label: 'Entregado ✓', status: 'delivered', bg: '#10B981'},\n  }\n  const next = NEXT[order.status]\n  const elapsed = Math.floor((Date.now() - new Date(order.created_at).getTime()) / 60000)\n\n  return (\n    <div className=\"bg-white rounded-xl border border-gray-100 p-3 shadow-sm\">\n      <div className=\"flex items-start justify-between gap-2 mb-2\">\n        <div>\n          <p className=\"text-xs font-bold text-gray-900\">#{String(order.order_number).padStart(4,'0')}</p>\n          <p className=\"text-sm font-semibold text-gray-900\">{order.customer_name}</p>\n        </div>\n        <div className=\"text-right shrink-0\">\n          <p className=\"text-sm font-bold\" style={{ color }}>{formatPrice(order.total, currency)}</p>\n          <p className=\"text-[10px] text-gray-400 flex items-center gap-0.5 justify-end\">\n            <Clock size={9} /> {elapsed}min\n          </p>\n        </div>\n      </div>\n\n      {/* Items */}\n      {!compact && order.items && order.items.length > 0 && (\n        <div className=\"mb-2 space-y-0.5\">\n          {order.items.map((item, i) => (\n            <p key={i} className=\"text-xs text-gray-600\">\n              <span className=\"font-bold\">{item.quantity}×</span> {item.product_name}\n            </p>\n          ))}\n        </div>\n      )}\n\n      {/* Tipo */}\n      <div className=\"flex items-center gap-1.5 mb-2\">\n        <span className={cn('badge text-[10px]',\n          order.delivery_type === 'delivery' ? 'bg-blue-50 text-blue-700' : 'bg-purple-50 text-purple-700')}>\n          {order.delivery_type === 'delivery' ? '🛵 Delivery' : '🏃 Retiro'}\n        </span>\n        {order.comment && (\n          <span className=\"badge bg-amber-50 text-amber-700 text-[10px]\">💬 Nota</span>\n        )}\n      </div>\n\n      {/* Acciones */}\n      <div className=\"flex items-center gap-1.5\">\n        {next && order.status !== 'delivered' && order.status !== 'cancelled' && (\n          <button onClick={() => onStatus(order.id, next.status)}\n            disabled={updating}\n            className=\"flex-1 flex items-center justify-center gap-1 rounded-lg py-2 text-xs font-bold text-white\n                       transition-all active:scale-[0.97] disabled:opacity-50\"\n            style={{ background: next.bg }}>\n            {updating ? <Loader2 size={11} className=\"animate-spin\" /> : null}\n            {next.label}\n          </button>\n        )}\n        {order.customer_phone && (\n          <button onClick={onWA}\n            className=\"flex h-8 w-8 items-center justify-center rounded-lg bg-green-500 text-white shrink-0\">\n            <MessageCircle size={13} />\n          </button>\n        )}\n        {order.status !== 'cancelled' && order.status !== 'delivered' && (\n          <button onClick={() => onStatus(order.id, 'cancelled')}\n            className=\"flex h-8 w-8 items-center justify-center rounded-lg bg-red-50 text-red-400 shrink-0 hover:bg-red-100\">\n            <X size={13} />\n          </button>\n        )}\n      </div>\n\n      {/* Comentario */}\n      {!compact && order.comment && (\n        <p className=\"mt-2 text-xs text-amber-700 bg-amber-50 rounded-lg px-2 py-1.5\">\n          💬 {order.comment}\n        </p>\n      )}\n    </div>\n  )\n}\n\n// ── Order Row ─────────────────────────────────────────────────\nfunction OrderRow({ order, currency, updating, onStatus, onWA, color }: {\n  order: Order; currency: string; updating: boolean\n  onStatus: (id: string, s: string) => void; onWA: () => void; color: string\n}) {\n  const [open, setOpen] = useState(false)\n  const NEXT_STATUS: Record<string, string> = {\n    pending:'confirmed', confirmed:'preparing', preparing:'ready', ready:'shipped', shipped:'delivered'\n  }\n  const PREV_STATUS: Record<string, string> = {\n    confirmed:'pending', preparing:'confirmed', ready:'preparing', shipped:'ready', delivered:'shipped'\n  }\n\n  return (\n    <div className=\"bg-white rounded-2xl border border-gray-100 overflow-hidden shadow-sm\">\n      <button onClick={() => setOpen(o => !o)}\n        className=\"w-full flex items-center gap-3 px-4 py-3.5 hover:bg-gray-50/50 transition-colors\">\n        <div className=\"shrink-0\">\n          <p className=\"text-xs font-mono text-gray-400\">#{String(order.order_number).padStart(4,'0')}</p>\n          <span className={`badge text-[10px] mt-0.5 ${orderStatusColor(order.status)}`}>\n            {orderStatusLabel(order.status)}\n          </span>\n        </div>\n        <div className=\"flex-1 min-w-0 text-left\">\n          <p className=\"text-sm font-bold text-gray-900\">{order.customer_name}</p>\n          <p className=\"text-xs text-gray-400 truncate\">\n            {order.delivery_type === 'delivery' ? '🛵 Delivery' : '🏃 Retiro'}\n            {order.customer_address ? ` · ${order.customer_address}` : ''}\n          </p>\n        </div>\n        <div className=\"text-right shrink-0\">\n          <p className=\"text-sm font-bold\" style={{ color }}>{formatPrice(order.total, currency)}</p>\n          <p className=\"text-[10px] text-gray-400\">\n            {new Date(order.created_at).toLocaleTimeString('es-UY', { hour: '2-digit', minute: '2-digit' })}\n          </p>\n        </div>\n        <ChevronRight size={14} className={cn('text-gray-300 transition-transform shrink-0', open && 'rotate-90')} />\n      </button>\n\n      {open && (\n        <div className=\"border-t border-gray-100 px-4 pb-4 pt-3 animate-fade-in space-y-3\">\n          {/* Items */}\n          {order.items && order.items.length > 0 && (\n            <div className=\"space-y-1.5\">\n              {order.items.map((item, i) => (\n                <div key={i} className=\"flex items-center justify-between\">\n                  <p className=\"text-sm text-gray-700\">\n                    <span className=\"font-bold text-gray-900\">{item.quantity}×</span> {item.product_name}\n                  </p>\n                  <p className=\"text-sm font-semibold text-gray-900\">{formatPrice(item.subtotal, currency)}</p>\n                </div>\n              ))}\n              <div className=\"flex justify-between pt-2 border-t border-gray-100\">\n                <p className=\"text-sm font-bold text-gray-900\">Total</p>\n                <p className=\"text-sm font-bold\" style={{ color }}>{formatPrice(order.total, currency)}</p>\n              </div>\n            </div>\n          )}\n\n          {/* Info cliente */}\n          <div className=\"rounded-xl bg-gray-50 px-3 py-2.5 space-y-1\">\n            {order.customer_phone && (\n              <p className=\"text-xs text-gray-600 flex items-center gap-1.5\">\n                <Phone size={11} /> {order.customer_phone}\n              </p>\n            )}\n            {order.customer_address && (\n              <p className=\"text-xs text-gray-600 flex items-center gap-1.5\">\n                <MapPin size={11} /> {order.customer_address}\n              </p>\n            )}\n            {order.comment && (\n              <p className=\"text-xs text-amber-700 flex items-start gap-1.5\">\n                💬 {order.comment}\n              </p>\n            )}\n          </div>\n\n          {/* Acciones de estado */}\n          <div className=\"flex items-center gap-2 flex-wrap\">\n            {NEXT_STATUS[order.status] && (\n              <button onClick={() => onStatus(order.id, NEXT_STATUS[order.status])}\n                disabled={updating}\n                className=\"flex items-center gap-1.5 rounded-xl px-3 py-2 text-xs font-bold text-white\n                           disabled:opacity-50\"\n                style={{ background: color }}>\n                {updating ? <Loader2 size={11} className=\"animate-spin\" /> : <ChevronRight size={11} />}\n                → {orderStatusLabel(NEXT_STATUS[order.status])}\n              </button>\n            )}\n            {order.customer_phone && (\n              <button onClick={onWA}\n                className=\"flex items-center gap-1.5 rounded-xl px-3 py-2 text-xs font-bold text-white bg-green-500\">\n                <MessageCircle size={11} /> WhatsApp\n              </button>\n            )}\n            {!['cancelled','delivered'].includes(order.status) && (\n              <button onClick={() => onStatus(order.id, 'cancelled')}\n                className=\"flex items-center gap-1 rounded-xl px-3 py-2 text-xs font-medium text-red-600 bg-red-50\">\n                <X size={11} /> Cancelar\n              </button>\n            )}\n          </div>\n        </div>\n      )}\n    </div>\n  )\n}\n\n// ── Hours Manager ─────────────────────────────────────────────\nfunction HoursManager({ businessId, hours, onUpdate, color }: {\n  businessId: string; hours: BusinessHours[]\n  onUpdate: (h: BusinessHours[]) => void; color: string\n}) {\n  const supabase = createClient()\n  const [saving, setSaving] = useState<number | null>(null)\n  const [local, setLocal] = useState<BusinessHours[]>(\n    DAYS_ES.map((_, i) => {\n      const found = hours.find(h => h.day_of_week === i)\n      return found ?? { id: '', business_id: businessId, branch_id: null, day_of_week: i, is_open: true, open_time: '09:00', close_time: '22:00' }\n    })\n  )\n\n  async function saveDay(h: BusinessHours) {\n    setSaving(h.day_of_week)\n    if (h.id) {\n      await supabase.from('business_hours').update({\n        is_open: h.is_open, open_time: h.open_time, close_time: h.close_time\n      }).eq('id', h.id)\n    } else {\n      const { data } = await supabase.from('business_hours').insert({\n        business_id: businessId, day_of_week: h.day_of_week,\n        is_open: h.is_open, open_time: h.open_time, close_time: h.close_time\n      }).select('*').single()\n      if (data) {\n        setLocal(prev => prev.map(x => x.day_of_week === h.day_of_week ? data as BusinessHours : x))\n      }\n    }\n    setSaving(null)\n  }\n\n  function update(day: number, field: keyof BusinessHours, value: unknown) {\n    setLocal(prev => prev.map(h => h.day_of_week === day ? { ...h, [field]: value } : h))\n  }\n\n  return (\n    <div className=\"space-y-4\">\n      <div>\n        <h2 className=\"text-sm font-bold text-gray-900 mb-1\">Horarios de atención</h2>\n        <p className=\"text-xs text-gray-400\">Configurá los días y horarios en que recibís pedidos</p>\n      </div>\n      <div className=\"bg-white rounded-2xl border border-gray-100 overflow-hidden shadow-sm divide-y divide-gray-50\">\n        {local.map(h => (\n          <div key={h.day_of_week} className=\"flex items-center gap-3 px-4 py-3\">\n            {/* Toggle abierto/cerrado */}\n            <button onClick={() => update(h.day_of_week, 'is_open', !h.is_open)}\n              className={cn('relative h-5 w-9 rounded-full transition-colors shrink-0',\n                h.is_open ? 'bg-green-500' : 'bg-gray-200')}>\n              <span className={cn('absolute top-0.5 h-4 w-4 rounded-full bg-white shadow transition-transform',\n                h.is_open ? 'left-4' : 'left-0.5')} />\n            </button>\n\n            {/* Día */}\n            <p className={cn('text-sm font-semibold w-8 shrink-0',\n              h.is_open ? 'text-gray-900' : 'text-gray-400')}>\n              {DAYS_ES[h.day_of_week]}\n            </p>\n\n            {/* Horarios */}\n            {h.is_open ? (\n              <div className=\"flex items-center gap-2 flex-1\">\n                <input type=\"time\" value={h.open_time}\n                  onChange={e => update(h.day_of_week, 'open_time', e.target.value)}\n                  className=\"rounded-xl border border-gray-200 px-2.5 py-1.5 text-xs font-medium text-gray-700 flex-1\" />\n                <span className=\"text-xs text-gray-400\">a</span>\n                <input type=\"time\" value={h.close_time}\n                  onChange={e => update(h.day_of_week, 'close_time', e.target.value)}\n                  className=\"rounded-xl border border-gray-200 px-2.5 py-1.5 text-xs font-medium text-gray-700 flex-1\" />\n              </div>\n            ) : (\n              <p className=\"text-xs text-gray-400 flex-1\">Cerrado</p>\n            )}\n\n            {/* Guardar */}\n            <button onClick={() => saveDay(h)}\n              disabled={saving === h.day_of_week}\n              className=\"flex h-7 w-7 items-center justify-center rounded-lg text-white shrink-0\n                         disabled:opacity-50\"\n              style={{ background: color }}>\n              {saving === h.day_of_week\n                ? <Loader2 size={11} className=\"animate-spin\" />\n                : <Check size={11} />}\n            </button>\n          </div>\n        ))}\n      </div>\n    </div>\n  )\n}\n\n// ── Food Stats ────────────────────────────────────────────────\nfunction FoodStats({ orders, currency, color }: { orders: Order[]; currency: string; color: string }) {\n  const confirmed = orders.filter(o => o.confirmed_sale)\n  const revenue = confirmed.reduce((a, o) => a + o.total, 0)\n  const avgTicket = confirmed.length > 0 ? revenue / confirmed.length : 0\n  const deliveries = orders.filter(o => o.delivery_type === 'delivery').length\n  const pickups = orders.filter(o => o.delivery_type === 'pickup').length\n\n  // Top productos del día\n  const productMap: Record<string, { qty: number; revenue: number }> = {}\n  orders.forEach(o => {\n    o.items?.forEach(item => {\n      if (!productMap[item.product_name]) productMap[item.product_name] = { qty: 0, revenue: 0 }\n      productMap[item.product_name].qty += item.quantity\n      productMap[item.product_name].revenue += item.subtotal\n    })\n  })\n  const topProducts = Object.entries(productMap)\n    .map(([name, v]) => ({ name, ...v }))\n    .sort((a, b) => b.qty - a.qty)\n    .slice(0, 5)\n\n  const maxQty = topProducts[0]?.qty ?? 1\n\n  return (\n    <div className=\"space-y-4\">\n      {/* KPIs */}\n      <div className=\"grid grid-cols-2 gap-3\">\n        {[\n          { label: 'Pedidos hoy', value: orders.length },\n          { label: 'Ingresos hoy', value: formatPrice(revenue, currency) },\n          { label: 'Ticket promedio', value: formatPrice(avgTicket, currency) },\n          { label: 'Cancelados', value: orders.filter(o => o.status === 'cancelled').length },\n        ].map(({ label, value }) => (\n          <div key={label} className=\"bg-white rounded-2xl border border-gray-100 p-4 shadow-sm\">\n            <p className=\"text-xs text-gray-400 mb-1\">{label}</p>\n            <p className=\"text-lg font-bold text-gray-900\">{value}</p>\n          </div>\n        ))}\n      </div>\n\n      {/* Delivery vs Retiro */}\n      <div className=\"bg-white rounded-2xl border border-gray-100 p-4 shadow-sm\">\n        <p className=\"text-sm font-semibold text-gray-700 mb-3\">Delivery vs Retiro</p>\n        <div className=\"flex items-center gap-3 mb-2\">\n          <div className=\"flex-1 bg-gray-100 rounded-full h-3 overflow-hidden\">\n            <div className=\"h-full rounded-full transition-all\"\n              style={{ width: `${orders.length > 0 ? (deliveries / orders.length) * 100 : 0}%`, background: color }} />\n          </div>\n          <p className=\"text-xs text-gray-600 shrink-0\">{deliveries} delivery</p>\n        </div>\n        <div className=\"flex items-center gap-3\">\n          <div className=\"flex-1 bg-gray-100 rounded-full h-3 overflow-hidden\">\n            <div className=\"h-full rounded-full bg-purple-400 transition-all\"\n              style={{ width: `${orders.length > 0 ? (pickups / orders.length) * 100 : 0}%` }} />\n          </div>\n          <p className=\"text-xs text-gray-600 shrink-0\">{pickups} retiro</p>\n        </div>\n      </div>\n\n      {/* Top productos del día */}\n      <div className=\"bg-white rounded-2xl border border-gray-100 p-4 shadow-sm\">\n        <p className=\"text-sm font-semibold text-gray-700 mb-3\">Más pedidos hoy</p>\n        {topProducts.length === 0 ? (\n          <p className=\"text-xs text-gray-400 text-center py-4\">Sin datos todavía</p>\n        ) : (\n          <div className=\"space-y-3\">\n            {topProducts.map((p, i) => (\n              <div key={p.name} className=\"flex items-center gap-2\">\n                <span className=\"text-xs font-bold w-4 text-center text-gray-400\">{i + 1}</span>\n                <div className=\"flex-1 min-w-0\">\n                  <div className=\"flex justify-between items-baseline mb-1\">\n                    <p className=\"text-xs font-medium text-gray-800 truncate\">{p.name}</p>\n                    <p className=\"text-xs text-gray-500 shrink-0 ml-1\">{p.qty} uds</p>\n                  </div>\n                  <div className=\"h-1.5 rounded-full bg-gray-100 overflow-hidden\">\n                    <div className=\"h-full rounded-full\"\n                      style={{ width: `${(p.qty / maxQty) * 100}%`, background: color }} />\n                  </div>\n                </div>\n              </div>\n            ))}\n          </div>\n        )}\n      </div>\n    </div>\n  )\n}\n"

files["components/food/FoodStore.tsx"] = "// components/food/FoodStore.tsx\n// Tienda pública gastronomía — mobile-first, tipo UberEats/PedidosYa\n'use client'\nimport { useState, useMemo, useRef } from 'react'\nimport { useCart } from '@/hooks/useCart'\nimport { formatPrice, productImageUrl } from '@/lib/utils'\nimport { buildWhatsAppMessage, getWhatsAppUrl } from '@/lib/whatsapp'\nimport {\n  Search, X, ShoppingBag, Plus, Minus, ChevronRight,\n  Clock, MapPin, Truck, Store, Star, ArrowLeft,\n  MessageCircle, Loader2, User, Phone, FileText,\n} from 'lucide-react'\nimport { cn } from '@/lib/utils'\nimport type { Business, Category, Product, BusinessHours, CheckoutFormData } from '@/types'\n\ninterface Props {\n  business: Business & {\n    delivery_fee?: number\n    delivery_enabled?: boolean\n    pickup_enabled?: boolean\n    min_order?: number\n    estimated_time?: string\n  }\n  categories: Category[]\n  products: Product[]\n  hours: BusinessHours[]\n}\n\nconst DAYS_ES = ['Dom','Lun','Mar','Mié','Jue','Vie','Sáb']\n\nfunction isOpen(hours: BusinessHours[]): { open: boolean; label: string } {\n  const now = new Date()\n  const day = now.getDay()\n  const time = now.toTimeString().slice(0, 5)\n  const todayHours = hours.find(h => h.day_of_week === day)\n  if (!todayHours || !todayHours.is_open) return { open: false, label: 'Cerrado hoy' }\n  if (time >= todayHours.open_time && time < todayHours.close_time)\n    return { open: true, label: `Abierto · Cierra ${todayHours.close_time}` }\n  if (time < todayHours.open_time)\n    return { open: false, label: `Abre a las ${todayHours.open_time}` }\n  return { open: false, label: 'Cerrado por hoy' }\n}\n\nexport default function FoodStore({ business, categories, products, hours }: Props) {\n  const { addItem, items, removeItem, updateQuantity, total, itemCount, clearCart } = useCart()\n  const [search, setSearch]           = useState('')\n  const [activeCat, setActiveCat]     = useState<string | null>(null)\n  const [cartOpen, setCartOpen]       = useState(false)\n  const [checkoutOpen, setCheckoutOpen] = useState(false)\n  const [addedId, setAddedId]         = useState<string | null>(null)\n  const catRefs = useRef<Record<string, HTMLDivElement | null>>({})\n\n  const color    = business.primary_color ?? '#FF5722'\n  const currency = business.currency ?? 'UYU'\n  const status   = isOpen(hours)\n  const count    = itemCount()\n  const cartTotal = total()\n\n  const featured = products.filter(p => p.featured)\n  const filtered = useMemo(() => {\n    let list = products\n    if (activeCat) list = list.filter(p => p.category_id === activeCat)\n    if (search.trim()) {\n      const q = search.toLowerCase()\n      list = list.filter(p =>\n        p.name.toLowerCase().includes(q) ||\n        p.description?.toLowerCase().includes(q)\n      )\n    }\n    return list\n  }, [products, activeCat, search])\n\n  function handleAdd(product: Product) {\n    addItem(product, business.slug)\n    setAddedId(product.id)\n    setTimeout(() => setAddedId(null), 900)\n  }\n\n  function scrollToCat(catId: string) {\n    setActiveCat(catId)\n    catRefs.current[catId]?.scrollIntoView({ behavior: 'smooth', block: 'start' })\n  }\n\n  return (\n    <div className=\"min-h-screen bg-[#F7F9FC]\">\n\n      {/* ── HERO HEADER ── */}\n      <div className=\"relative\">\n        {/* Banner */}\n        <div className=\"h-40 sm:h-52 overflow-hidden bg-gray-200\"\n          style={{ background: business.banner_url ? undefined : `linear-gradient(135deg,${color},${color}88)` }}>\n          {business.banner_url && (\n            <img src={business.banner_url} alt={business.name}\n              className=\"h-full w-full object-cover\" />\n          )}\n          <div className=\"absolute inset-0 bg-black/30\" />\n        </div>\n\n        {/* Info sobre el banner */}\n        <div className=\"absolute bottom-0 left-0 right-0 px-4 pb-4\">\n          <div className=\"flex items-end gap-3\">\n            {business.logo_url ? (\n              <img src={business.logo_url} alt={business.name}\n                className=\"h-14 w-14 rounded-2xl object-cover ring-2 ring-white shrink-0\" />\n            ) : (\n              <div className=\"h-14 w-14 rounded-2xl flex items-center justify-center text-white\n                              text-lg font-bold ring-2 ring-white shrink-0\"\n                style={{ background: color }}>\n                {business.name.slice(0, 2).toUpperCase()}\n              </div>\n            )}\n            <div className=\"pb-1\">\n              <h1 className=\"text-white font-bold text-lg leading-tight\">{business.name}</h1>\n              <div className=\"flex items-center gap-2 mt-0.5\">\n                <span className={cn('flex items-center gap-1 text-xs font-medium',\n                  status.open ? 'text-green-400' : 'text-red-400')}>\n                  <span className={cn('h-1.5 w-1.5 rounded-full', status.open ? 'bg-green-400' : 'bg-red-400')} />\n                  {status.label}\n                </span>\n              </div>\n            </div>\n          </div>\n        </div>\n\n        {/* Cart button top-right */}\n        <button onClick={() => setCartOpen(true)}\n          className=\"absolute top-3 right-3 flex h-10 w-10 items-center justify-center\n                     rounded-xl bg-white/90 backdrop-blur-sm shadow-md\">\n          <ShoppingBag size={18} className=\"text-gray-700\" />\n          {count > 0 && (\n            <span className=\"absolute -top-1 -right-1 flex h-5 w-5 items-center justify-center\n                             rounded-full text-[10px] font-bold text-white\"\n              style={{ background: color }}>\n              {count}\n            </span>\n          )}\n        </button>\n      </div>\n\n      {/* ── INFO RÁPIDA ── */}\n      <div className=\"bg-white border-b border-gray-100\">\n        <div className=\"max-w-2xl mx-auto px-4 py-3 flex items-center gap-4 overflow-x-auto scrollbar-hide\">\n          {business.estimated_time && (\n            <div className=\"flex items-center gap-1.5 text-xs text-gray-600 shrink-0\">\n              <Clock size={13} className=\"text-gray-400\" />\n              {business.estimated_time}\n            </div>\n          )}\n          {business.delivery_enabled && (\n            <div className=\"flex items-center gap-1.5 text-xs text-gray-600 shrink-0\">\n              <Truck size={13} className=\"text-gray-400\" />\n              {business.delivery_fee && business.delivery_fee > 0\n                ? `Delivery ${formatPrice(business.delivery_fee, currency)}`\n                : 'Delivery gratis'\n              }\n            </div>\n          )}\n          {business.pickup_enabled && (\n            <div className=\"flex items-center gap-1.5 text-xs text-gray-600 shrink-0\">\n              <Store size={13} className=\"text-gray-400\" />\n              Retiro disponible\n            </div>\n          )}\n          {business.min_order && business.min_order > 0 && (\n            <div className=\"flex items-center gap-1.5 text-xs text-gray-600 shrink-0\">\n              Mín. {formatPrice(business.min_order, currency)}\n            </div>\n          )}\n        </div>\n      </div>\n\n      {/* ── BUSCADOR ── */}\n      <div className=\"sticky top-0 z-20 bg-white border-b border-gray-100 px-4 py-2.5\">\n        <div className=\"relative max-w-2xl mx-auto\">\n          <Search size={14} className=\"absolute left-3.5 top-1/2 -translate-y-1/2 text-gray-400\" />\n          <input type=\"text\" value={search} onChange={e => setSearch(e.target.value)}\n            placeholder=\"Buscar en el menú...\"\n            className=\"w-full rounded-xl bg-gray-100 pl-9 pr-3 py-2.5 text-sm\n                       placeholder:text-gray-400 focus:outline-none focus:bg-gray-200 transition-colors\" />\n          {search && (\n            <button onClick={() => setSearch('')}\n              className=\"absolute right-3 top-1/2 -translate-y-1/2 text-gray-400\">\n              <X size={13} />\n            </button>\n          )}\n        </div>\n      </div>\n\n      <div className=\"max-w-2xl mx-auto pb-32\">\n        {/* ── CATEGORÍAS SCROLL ── */}\n        {categories.length > 0 && !search && (\n          <div className=\"sticky top-[53px] z-10 bg-white border-b border-gray-100\">\n            <div className=\"flex items-center gap-2 px-4 py-2.5 overflow-x-auto scrollbar-hide\">\n              <button onClick={() => setActiveCat(null)}\n                className={cn('shrink-0 rounded-full px-3.5 py-1.5 text-xs font-semibold transition-all',\n                  !activeCat ? 'text-white' : 'bg-gray-100 text-gray-600 hover:bg-gray-200')}\n                style={!activeCat ? { background: color } : {}}>\n                Todo\n              </button>\n              {categories.map(cat => (\n                <button key={cat.id} onClick={() => scrollToCat(cat.id)}\n                  className={cn('shrink-0 rounded-full px-3.5 py-1.5 text-xs font-semibold transition-all',\n                    activeCat === cat.id ? 'text-white' : 'bg-gray-100 text-gray-600 hover:bg-gray-200')}\n                  style={activeCat === cat.id ? { background: color } : {}}>\n                  {cat.name}\n                </button>\n              ))}\n            </div>\n          </div>\n        )}\n\n        {/* ── DESTACADOS ── */}\n        {featured.length > 0 && !activeCat && !search && (\n          <div className=\"px-4 pt-5 pb-2\">\n            <p className=\"text-sm font-bold text-gray-700 mb-3\">⭐ Destacados</p>\n            <div className=\"flex gap-3 overflow-x-auto pb-1 scrollbar-hide -mx-4 px-4\">\n              {featured.map(p => (\n                <FeaturedCard key={p.id} product={p} currency={currency}\n                  added={addedId === p.id} onAdd={() => handleAdd(p)} color={color} />\n              ))}\n            </div>\n          </div>\n        )}\n\n        {/* ── PRODUCTOS POR CATEGORÍA ── */}\n        {categories.length > 0 && !activeCat && !search ? (\n          categories.map(cat => {\n            const catProducts = filtered.filter(p => p.category_id === cat.id)\n            if (catProducts.length === 0) return null\n            return (\n              <div key={cat.id} ref={el => { catRefs.current[cat.id] = el }} className=\"px-4 pt-5\">\n                <p className=\"text-sm font-bold text-gray-800 mb-3\">{cat.name}</p>\n                <div className=\"space-y-2\">\n                  {catProducts.map(p => (\n                    <MenuRow key={p.id} product={p} currency={currency}\n                      items={items} added={addedId === p.id}\n                      onAdd={() => handleAdd(p)}\n                      onRemove={() => removeItem(p.id)}\n                      onQty={(qty) => updateQuantity(p.id, qty)}\n                      color={color} />\n                  ))}\n                </div>\n              </div>\n            )\n          })\n        ) : (\n          <div className=\"px-4 pt-5\">\n            {activeCat && <p className=\"text-sm font-bold text-gray-800 mb-3\">\n              {categories.find(c => c.id === activeCat)?.name}\n            </p>}\n            {search && <p className=\"text-sm text-gray-400 mb-3\">{filtered.length} resultados</p>}\n            <div className=\"space-y-2\">\n              {filtered.map(p => (\n                <MenuRow key={p.id} product={p} currency={currency}\n                  items={items} added={addedId === p.id}\n                  onAdd={() => handleAdd(p)}\n                  onRemove={() => removeItem(p.id)}\n                  onQty={(qty) => updateQuantity(p.id, qty)}\n                  color={color} />\n              ))}\n            </div>\n          </div>\n        )}\n      </div>\n\n      {/* ── BOTÓN FLOTANTE CARRITO ── */}\n      {count > 0 && (\n        <div className=\"fixed bottom-4 left-0 right-0 flex justify-center z-20 px-4\">\n          <button onClick={() => setCartOpen(true)}\n            className=\"flex items-center justify-between gap-4 rounded-2xl px-5 py-3.5\n                       text-white shadow-2xl w-full max-w-sm font-semibold transition-all active:scale-[0.97]\"\n            style={{ background: color }}>\n            <span className=\"flex h-6 w-6 items-center justify-center rounded-full bg-white/20 text-xs font-bold\">\n              {count}\n            </span>\n            <span className=\"text-sm flex-1 text-center\">Ver pedido</span>\n            <span className=\"text-sm\">{formatPrice(cartTotal, currency)}</span>\n          </button>\n        </div>\n      )}\n\n      {/* ── CART DRAWER ── */}\n      {cartOpen && (\n        <FoodCartDrawer\n          items={items}\n          business={business}\n          currency={currency}\n          color={color}\n          onClose={() => setCartOpen(false)}\n          onCheckout={() => { setCartOpen(false); setCheckoutOpen(true) }}\n          onRemove={removeItem}\n          onQty={updateQuantity}\n        />\n      )}\n\n      {/* ── CHECKOUT ── */}\n      {checkoutOpen && (\n        <FoodCheckout\n          items={items}\n          business={business}\n          currency={currency}\n          color={color}\n          onClose={() => setCheckoutOpen(false)}\n          onSuccess={() => { clearCart(); setCheckoutOpen(false) }}\n        />\n      )}\n    </div>\n  )\n}\n\n// ── Featured Card ─────────────────────────────────────────────\nfunction FeaturedCard({ product, currency, added, onAdd, color }: {\n  product: Product; currency: string; added: boolean; onAdd: () => void; color: string\n}) {\n  return (\n    <div className=\"shrink-0 w-40 bg-white rounded-2xl overflow-hidden border border-gray-100 shadow-sm\">\n      <div className=\"h-28 bg-gray-100 overflow-hidden\">\n        <img src={productImageUrl(product.images)} alt={product.name}\n          className=\"h-full w-full object-cover\"\n          onError={e => { (e.target as HTMLImageElement).src = '/placeholder-product.png' }} />\n      </div>\n      <div className=\"p-2.5\">\n        <p className=\"text-xs font-bold text-gray-900 line-clamp-2 leading-tight mb-1\">{product.name}</p>\n        <p className=\"text-xs font-bold mb-2\" style={{ color }}>{formatPrice(product.price, currency)}</p>\n        <button onClick={onAdd}\n          className={cn('w-full rounded-xl py-1.5 text-xs font-bold transition-all',\n            added ? 'bg-green-500 text-white' : 'text-white')}\n          style={!added ? { background: color } : {}}>\n          {added ? '✓ Agregado' : 'Agregar'}\n        </button>\n      </div>\n    </div>\n  )\n}\n\n// ── Menu Row ──────────────────────────────────────────────────\nfunction MenuRow({ product, currency, items, added, onAdd, onRemove, onQty, color }: {\n  product: Product; currency: string\n  items: { product: Product; quantity: number }[]\n  added: boolean; onAdd: () => void; onRemove: () => void\n  onQty: (qty: number) => void; color: string\n}) {\n  const inCart = items.find(i => i.product.id === product.id)\n  const qty = inCart?.quantity ?? 0\n\n  return (\n    <div className=\"flex items-center gap-3 bg-white rounded-2xl border border-gray-100 p-3 shadow-sm\">\n      <div className=\"h-16 w-16 rounded-xl overflow-hidden bg-gray-100 shrink-0\">\n        <img src={productImageUrl(product.images)} alt={product.name}\n          className=\"h-full w-full object-cover\"\n          onError={e => { (e.target as HTMLImageElement).src = '/placeholder-product.png' }} />\n      </div>\n      <div className=\"flex-1 min-w-0\">\n        <p className=\"text-sm font-bold text-gray-900 leading-tight\">{product.name}</p>\n        {product.description && (\n          <p className=\"text-xs text-gray-500 mt-0.5 line-clamp-2 leading-relaxed\">{product.description}</p>\n        )}\n        <p className=\"text-sm font-bold mt-1\" style={{ color }}>{formatPrice(product.price, currency)}</p>\n      </div>\n      {qty === 0 ? (\n        <button onClick={onAdd}\n          className={cn('flex h-9 w-9 items-center justify-center rounded-xl text-white shrink-0',\n            'transition-all active:scale-90', added ? 'bg-green-500' : '')}\n          style={!added ? { background: color } : {}}>\n          <Plus size={18} />\n        </button>\n      ) : (\n        <div className=\"flex items-center gap-1.5 shrink-0\">\n          <button onClick={() => onQty(qty - 1)}\n            className=\"flex h-8 w-8 items-center justify-center rounded-xl border border-gray-200\n                       text-gray-600 hover:border-gray-400 transition-colors active:scale-90\">\n            <Minus size={14} />\n          </button>\n          <span className=\"text-sm font-bold text-gray-900 w-5 text-center\">{qty}</span>\n          <button onClick={onAdd}\n            className=\"flex h-8 w-8 items-center justify-center rounded-xl text-white active:scale-90\"\n            style={{ background: color }}>\n            <Plus size={14} />\n          </button>\n        </div>\n      )}\n    </div>\n  )\n}\n\n// ── Cart Drawer ───────────────────────────────────────────────\nfunction FoodCartDrawer({ items, business, currency, color, onClose, onCheckout, onRemove, onQty }: {\n  items: { product: Product; quantity: number }[]\n  business: Props['business']; currency: string; color: string\n  onClose: () => void; onCheckout: () => void\n  onRemove: (id: string) => void; onQty: (id: string, qty: number) => void\n}) {\n  const cartTotal = items.reduce((a, i) => a + i.product.price * i.quantity, 0)\n  const deliveryFee = business.delivery_fee ?? 0\n\n  return (\n    <div className=\"fixed inset-0 z-50 flex items-end justify-center\">\n      <div className=\"absolute inset-0 bg-black/40 backdrop-blur-sm\" onClick={onClose} />\n      <div className=\"relative bg-white w-full max-w-lg rounded-t-3xl shadow-2xl max-h-[85vh] flex flex-col animate-slide-up\">\n        <div className=\"flex justify-center pt-3 pb-1\">\n          <div className=\"h-1 w-10 rounded-full bg-gray-200\" />\n        </div>\n        <div className=\"flex items-center justify-between px-5 py-3 border-b border-gray-100\">\n          <p className=\"font-bold text-gray-900\">Tu pedido ({items.reduce((a,i)=>a+i.quantity,0)} items)</p>\n          <button onClick={onClose} className=\"h-8 w-8 flex items-center justify-center rounded-xl text-gray-400 hover:bg-gray-100\">\n            <X size={16} />\n          </button>\n        </div>\n\n        <div className=\"flex-1 overflow-y-auto px-4 py-3 space-y-2\">\n          {items.map(({ product, quantity }) => (\n            <div key={product.id} className=\"flex items-center gap-3 bg-gray-50 rounded-xl p-3\">\n              <div className=\"h-12 w-12 rounded-lg overflow-hidden bg-gray-200 shrink-0\">\n                <img src={productImageUrl(product.images)} alt={product.name}\n                  className=\"h-full w-full object-cover\" />\n              </div>\n              <div className=\"flex-1 min-w-0\">\n                <p className=\"text-sm font-semibold text-gray-900 truncate\">{product.name}</p>\n                <p className=\"text-xs text-gray-500\">{formatPrice(product.price, currency)} c/u</p>\n              </div>\n              <div className=\"flex items-center gap-1.5 shrink-0\">\n                <button onClick={() => onQty(product.id, quantity - 1)}\n                  className=\"flex h-7 w-7 items-center justify-center rounded-lg border border-gray-200 text-gray-600\">\n                  <Minus size={12} />\n                </button>\n                <span className=\"text-sm font-bold w-4 text-center\">{quantity}</span>\n                <button onClick={() => onQty(product.id, quantity + 1)}\n                  className=\"flex h-7 w-7 items-center justify-center rounded-lg text-white\"\n                  style={{ background: color }}>\n                  <Plus size={12} />\n                </button>\n              </div>\n              <p className=\"text-sm font-bold text-gray-900 w-16 text-right shrink-0\">\n                {formatPrice(product.price * quantity, currency)}\n              </p>\n            </div>\n          ))}\n        </div>\n\n        <div className=\"border-t border-gray-100 px-5 py-4 space-y-3\">\n          <div className=\"flex justify-between text-sm\">\n            <span className=\"text-gray-500\">Subtotal</span>\n            <span className=\"font-semibold\">{formatPrice(cartTotal, currency)}</span>\n          </div>\n          {deliveryFee > 0 && (\n            <div className=\"flex justify-between text-sm\">\n              <span className=\"text-gray-500\">Delivery</span>\n              <span className=\"font-semibold\">{formatPrice(deliveryFee, currency)}</span>\n            </div>\n          )}\n          <div className=\"flex justify-between text-base font-bold\">\n            <span>Total</span>\n            <span style={{ color }}>{formatPrice(cartTotal + deliveryFee, currency)}</span>\n          </div>\n          <button onClick={onCheckout}\n            className=\"w-full flex items-center justify-center gap-2 rounded-2xl py-4 text-sm font-bold text-white\"\n            style={{ background: color }}>\n            Continuar con el pedido <ChevronRight size={16} />\n          </button>\n        </div>\n      </div>\n    </div>\n  )\n}\n\n// ── Checkout ──────────────────────────────────────────────────\nfunction FoodCheckout({ items, business, currency, color, onClose, onSuccess }: {\n  items: { product: Product; quantity: number }[]\n  business: Props['business']; currency: string; color: string\n  onClose: () => void; onSuccess: () => void\n}) {\n  const [form, setForm] = useState<CheckoutFormData>({\n    name: '', phone: '', address: '', delivery_type: 'delivery', comment: ''\n  })\n  const [submitting, setSubmitting] = useState(false)\n  const [error, setError] = useState<string | null>(null)\n\n  const cartTotal = items.reduce((a, i) => a + i.product.price * i.quantity, 0)\n  const deliveryFee = form.delivery_type === 'delivery' ? (business.delivery_fee ?? 0) : 0\n  const waOk = (business.whatsapp ?? '').replace(/\\D/g,'').length >= 8\n\n  function set<K extends keyof CheckoutFormData>(key: K, val: CheckoutFormData[K]) {\n    setForm(prev => ({ ...prev, [key]: val })); setError(null)\n  }\n\n  async function handleSubmit(e: React.FormEvent) {\n    e.preventDefault()\n    if (!form.name.trim() || !form.phone.trim()) return\n    if (form.delivery_type === 'delivery' && !form.address?.trim()) {\n      setError('Ingresá la dirección de entrega'); return\n    }\n    if (!waOk) { setError('El comercio no tiene WhatsApp configurado'); return }\n\n    setSubmitting(true); setError(null)\n    try {\n      const res = await fetch('/api/orders', {\n        method: 'POST',\n        headers: { 'Content-Type': 'application/json' },\n        body: JSON.stringify({\n          businessId: business.id, items,\n          customerName: form.name.trim(), customerPhone: form.phone.trim(),\n          customerAddress: form.delivery_type === 'delivery' ? form.address?.trim() : null,\n          deliveryType: form.delivery_type, comment: form.comment?.trim() || null,\n        }),\n      })\n      if (!res.ok) { const d = await res.json(); throw new Error(d.error ?? 'Error') }\n\n      const msg = buildWhatsAppMessage(items, form, currency)\n      const waUrl = getWhatsAppUrl(business.whatsapp!, msg)\n      window.open(waUrl, '_blank')\n      onSuccess()\n    } catch(e: unknown) {\n      setError(e instanceof Error ? e.message : 'Error desconocido')\n      setSubmitting(false)\n    }\n  }\n\n  return (\n    <div className=\"fixed inset-0 z-50 flex items-end justify-center\">\n      <div className=\"absolute inset-0 bg-black/40 backdrop-blur-sm\" onClick={onClose} />\n      <div className=\"relative bg-white w-full max-w-lg rounded-t-3xl shadow-2xl max-h-[92vh] overflow-y-auto animate-slide-up\">\n        <div className=\"flex justify-center pt-3 pb-1\">\n          <div className=\"h-1 w-10 rounded-full bg-gray-200\" />\n        </div>\n        <div className=\"flex items-center gap-3 px-5 py-3 border-b border-gray-100 sticky top-0 bg-white z-10\">\n          <button onClick={onClose} className=\"h-8 w-8 flex items-center justify-center rounded-xl text-gray-400 hover:bg-gray-100\">\n            <ArrowLeft size={16} />\n          </button>\n          <p className=\"font-bold text-gray-900\">Completar pedido</p>\n        </div>\n\n        <form onSubmit={handleSubmit} className=\"px-5 py-4 space-y-4 pb-8\">\n          {/* Resumen */}\n          <div className=\"rounded-2xl bg-gray-50 px-4 py-3 space-y-1.5\">\n            {items.map(({ product, quantity }) => (\n              <div key={product.id} className=\"flex justify-between text-sm\">\n                <span className=\"text-gray-700\">{quantity}× {product.name}</span>\n                <span className=\"font-medium text-gray-900\">{formatPrice(product.price * quantity, currency)}</span>\n              </div>\n            ))}\n            {deliveryFee > 0 && (\n              <div className=\"flex justify-between text-sm border-t border-gray-200 pt-1.5 mt-1.5\">\n                <span className=\"text-gray-500\">Delivery</span>\n                <span>{formatPrice(deliveryFee, currency)}</span>\n              </div>\n            )}\n            <div className=\"flex justify-between font-bold text-base border-t border-gray-200 pt-1.5\">\n              <span>Total</span>\n              <span style={{ color }}>{formatPrice(cartTotal + deliveryFee, currency)}</span>\n            </div>\n          </div>\n\n          {/* Entrega */}\n          <div>\n            <p className=\"field-label mb-2\">Tipo de entrega</p>\n            <div className=\"grid grid-cols-2 gap-2\">\n              {[\n                { val: 'delivery', label: '🛵 Delivery', sub: 'Lo llevamos', enabled: business.delivery_enabled ?? true },\n                { val: 'pickup',   label: '🏃 Retiro',   sub: 'Paso a buscar', enabled: business.pickup_enabled ?? true },\n              ].filter(o => o.enabled).map(({ val, label, sub }) => (\n                <button key={val} type=\"button\" onClick={() => set('delivery_type', val as 'delivery'|'pickup')}\n                  className={cn('rounded-xl border-2 p-3 text-left transition-all',\n                    form.delivery_type === val ? 'border-gray-900 bg-gray-50' : 'border-gray-100')}>\n                  <p className=\"text-sm font-bold text-gray-900\">{label}</p>\n                  <p className=\"text-xs text-gray-400\">{sub}</p>\n                </button>\n              ))}\n            </div>\n          </div>\n\n          {/* Datos */}\n          <div className=\"space-y-3\">\n            <div>\n              <label className=\"field-label\">Nombre <span className=\"text-red-400\">*</span></label>\n              <div className=\"relative\">\n                <User size={14} className=\"absolute left-3.5 top-1/2 -translate-y-1/2 text-gray-400\" />\n                <input type=\"text\" required value={form.name} onChange={e => set('name', e.target.value)}\n                  placeholder=\"Tu nombre\" className=\"input-base pl-9\" />\n              </div>\n            </div>\n            <div>\n              <label className=\"field-label\">Teléfono <span className=\"text-red-400\">*</span></label>\n              <div className=\"relative\">\n                <Phone size={14} className=\"absolute left-3.5 top-1/2 -translate-y-1/2 text-gray-400\" />\n                <input type=\"tel\" required value={form.phone} onChange={e => set('phone', e.target.value)}\n                  placeholder=\"099 123 456\" className=\"input-base pl-9\" inputMode=\"numeric\" />\n              </div>\n            </div>\n            {form.delivery_type === 'delivery' && (\n              <div>\n                <label className=\"field-label\">Dirección <span className=\"text-red-400\">*</span></label>\n                <input type=\"text\" value={form.address} onChange={e => set('address', e.target.value)}\n                  placeholder=\"Calle, número, piso...\" className=\"input-base\" />\n              </div>\n            )}\n            <div>\n              <label className=\"field-label\">\n                Comentario <span className=\"text-gray-400 font-normal text-xs\">(sin gluten, sin cebolla...)</span>\n              </label>\n              <textarea value={form.comment} onChange={e => set('comment', e.target.value)} rows={2}\n                placeholder=\"Aclaraciones del pedido\" className=\"input-base resize-none\" />\n            </div>\n          </div>\n\n          {error && (\n            <div className=\"rounded-xl bg-red-50 px-4 py-3 text-sm text-red-700\">{error}</div>\n          )}\n\n          <button type=\"submit\" disabled={submitting || !waOk}\n            className=\"w-full flex items-center justify-center gap-2 rounded-2xl py-4 text-sm font-bold\n                       text-white disabled:opacity-50 transition-all active:scale-[0.98]\"\n            style={{ background: color }}>\n            {submitting ? <Loader2 size={16} className=\"animate-spin\" /> : <MessageCircle size={16} />}\n            {submitting ? 'Enviando...' : 'Enviar pedido por WhatsApp'}\n          </button>\n\n          <p className=\"text-center text-xs text-gray-400\">\n            Se abrirá WhatsApp con tu pedido ya armado · Solo tocás Enviar\n          </p>\n        </form>\n      </div>\n    </div>\n  )\n}\n"

for (const [p,c] of Object.entries(files)) {
  const d = path.dirname(p)
  if (!fs.existsSync(d)) fs.mkdirSync(d,{recursive:true})
  fs.writeFileSync(p,c,'utf8')
  console.log('  OK ' + p)
}
